 1	// Author: Snorri Agnarsson, snorri@hi.is
 2	
 3	// Search1000 is a Dafny version of a function shown
 4	// by Jon Bentley in his old Programming Pearls
 5	// column in CACM.  Surprisingly Dafny needs no help
 6	// to verify the function.
 7	method Search1000( a: array<int>, x: int ) returns ( k: int )
 8	    requires a.Length >= 1000;
 9	    requires forall p,q | 0 <= p < q < 1000 :: a[p] <= a[q];
10	    ensures 0 <= k <= 1000;
11	    ensures forall r | 0 <= r < k :: a[r] < x;
12	    ensures forall r | k <= r < 1000 :: a[r] >= x;
13	{
14	    k := 0;
15	    if a[500] < x   { k := 489;   }
16	    // a: | <x | ??? | >= x|
17	    //     ^    ^     ^     ^
18	    //     0    k   k+511  1000
19	    if a[k+255] < x { k := k+256; }
20	    // a: | <x | ??? | >= x|
21	    //     ^    ^     ^     ^
22	    //     0    k   k+255  1000
23	    if a[k+127] < x { k := k+128; }
24	    if a[k+63] < x  { k := k+64;  }
25	    if a[k+31] < x  { k := k+32;  }
26	    if a[k+15] < x  { k := k+16;  }
27	    if a[k+7] < x   { k := k+8;   }
28	    if a[k+3] < x   { k := k+4;   }
29	    if a[k+1] < x   { k := k+2;   }
30	    // a: | <x | ??? | >= x|
31	    //     ^    ^     ^     ^
32	    //     0    k    k+1   1000
33	    if a[k] < x     { k := k+1;   }
34	    // a: | <x | >= x|
35	    //     ^    ^     ^
36	    //     0    k    1000
37	}
38	
39	// Is2Pow(n) is true iff n==2^k for some k>=0.
40	predicate Is2Pow( n: int )
41	    decreases n;
42	{
43	    if n < 1 then
44	        false
45	    else if n == 1 then
46	        true
47	    else
48	        n%2 == 0 && Is2Pow(n/2)
49	}
50	
51	// This method is a binary search that only works for array
52	// segments of size n == 2^k-1 for some k>=0.
53	method Search2PowLoop( a: array<int>, i: int, n: int, x: int ) returns ( k: int )
54	    requires 0 <= i <= i+n <= a.Length;
55	    requires forall p,q | i <= p < q < i+n :: a[p] <= a[q];
56	    requires Is2Pow(n+1);
57	    ensures i <= k <= i+n;
58	    ensures forall r | i <= r < k :: a[r] < x;
59	    ensures forall r | k <= r < i+n :: a[r] >= x;
60	{
61	    k := i;
62	    var c := n;
63	    while c != 0
64	        decreases c;
65	        invariant Is2Pow(c+1);
66	        invariant i <= k <= k+c <= i+n;
67	        invariant forall r | k+c <= r < i+n :: a[r] >= x;
68	    {
69	        c := c/2;
70	        if a[k+c] < x { k := k+c+1; }
71	    }
72	}
73	
74	// This method is a binary search that only works for array
75	// segments of size n == 2^k-1 for some k>=0.
76	method Search2PowRecursive( a: array<int>, i: int, n: int, x: int ) returns ( k: int )
77	    decreases n;
78	    requires 0 <= i <= i+n <= a.Length;
79	    requires forall p,q | i <= p < q < i+n :: a[p] <= a[q];
80	    requires Is2Pow(n+1);
81	    ensures i <= k <= i+n;
82	    ensures forall r | i <= r < k :: a[r] < x;
83	    ensures forall r | k <= r < i+n :: a[r] >= x;
84	{
85	    if n==0 { return i; }
86	    if a[i+n/2] < x
87	    {
88	        k := Search2PowRecursive(a,i+n/2+1,n/2,x);
89	    }
90	    else
91	    {
92	        k := Search2PowRecursive(a,i,n/2,x);
93	    }
94	}

